-- PostgreSQL schema (generated from the SQLite schema; NOT yet exercised by the runtime, which still uses node:sqlite).
-- Money columns are *_paisa BIGINT. Review types/defaults, then apply with psql before porting the data layer.
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, phone TEXT UNIQUE NOT NULL, email TEXT, name TEXT NOT NULL, password TEXT NOT NULL, role TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'ACTIVE', phone_verified BIGINT NOT NULL DEFAULT 0, email_verified BIGINT NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS otp_codes(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, purpose TEXT NOT NULL, code_hash TEXT NOT NULL, attempts BIGINT NOT NULL DEFAULT 0, expires_at TEXT NOT NULL, used_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS seller_profiles(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, shop_name TEXT UNIQUE NOT NULL, shop_address TEXT NOT NULL, business_info TEXT NOT NULL DEFAULT '', kyc_nid TEXT NOT NULL DEFAULT '', kyc_trade_license TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'PENDING', commission_bps BIGINT NOT NULL DEFAULT 800, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS addresses(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, label TEXT NOT NULL DEFAULT '', name TEXT NOT NULL, phone TEXT NOT NULL, address TEXT NOT NULL, area TEXT NOT NULL, is_default BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS categories(id TEXT PRIMARY KEY, slug TEXT UNIQUE, name_bn TEXT NOT NULL, name_en TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS brands(id TEXT PRIMARY KEY, slug TEXT UNIQUE NOT NULL, name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY, category_id TEXT, name_bn TEXT NOT NULL, name_en TEXT NOT NULL, price_paisa BIGINT NOT NULL, stock BIGINT NOT NULL, active BIGINT NOT NULL DEFAULT 1, seller_id TEXT, status TEXT NOT NULL DEFAULT 'ACTIVE', brand_id TEXT, description TEXT NOT NULL DEFAULT '', discount_paisa BIGINT, sku TEXT, variants TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL DEFAULT '', updated_at TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS product_images(id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, url TEXT NOT NULL, position BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS wishlists(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, created_at TEXT NOT NULL, PRIMARY KEY(user_id,product_id));
CREATE TABLE IF NOT EXISTS cart_items(user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, quantity BIGINT NOT NULL CHECK(quantity>0), PRIMARY KEY(user_id,product_id));
CREATE TABLE IF NOT EXISTS coupons(code TEXT PRIMARY KEY, type TEXT NOT NULL, value BIGINT NOT NULL, min_order_paisa BIGINT NOT NULL DEFAULT 0, max_uses BIGINT, used_count BIGINT NOT NULL DEFAULT 0, expires_at TEXT, active BIGINT NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS orders(id TEXT PRIMARY KEY, user_id TEXT NOT NULL, total_paisa BIGINT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, delivery_name TEXT NOT NULL DEFAULT '', delivery_phone TEXT NOT NULL DEFAULT '', delivery_address TEXT NOT NULL DEFAULT '', delivery_area TEXT NOT NULL DEFAULT '', customer_note TEXT NOT NULL DEFAULT '', subtotal_paisa BIGINT NOT NULL DEFAULT 0, shipping_paisa BIGINT NOT NULL DEFAULT 0, discount_paisa BIGINT NOT NULL DEFAULT 0, coupon_code TEXT, payment_method TEXT NOT NULL DEFAULT 'COD', payment_status TEXT NOT NULL DEFAULT 'PENDING', admin_note TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS seller_orders(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, seller_id TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'CONFIRMED', subtotal_paisa BIGINT NOT NULL, created_at TEXT NOT NULL, commission_paisa BIGINT NOT NULL DEFAULT 0, net_paisa BIGINT NOT NULL DEFAULT 0, UNIQUE(order_id,seller_id));
CREATE TABLE IF NOT EXISTS order_items(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id TEXT NOT NULL, product_name_bn TEXT NOT NULL, quantity BIGINT NOT NULL, unit_price_paisa BIGINT NOT NULL, seller_id TEXT, seller_order_id TEXT, variant TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS order_events(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, seller_order_id TEXT, status TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', actor_id TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS payments(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE, method TEXT NOT NULL, amount_paisa BIGINT NOT NULL, status TEXT NOT NULL, gateway_txn_id TEXT, raw TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL, UNIQUE(method,gateway_txn_id));
CREATE TABLE IF NOT EXISTS transactions(id TEXT PRIMARY KEY, kind TEXT NOT NULL, order_id TEXT, seller_order_id TEXT, seller_id TEXT, amount_paisa BIGINT NOT NULL, ref TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(kind,ref));
CREATE TABLE IF NOT EXISTS payouts(id TEXT PRIMARY KEY, seller_id TEXT NOT NULL, amount_paisa BIGINT NOT NULL CHECK(amount_paisa>0), method TEXT NOT NULL, account TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'REQUESTED', note TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, decided_at TEXT);
CREATE TABLE IF NOT EXISTS refunds(id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), amount_paisa BIGINT NOT NULL, reason TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'REQUESTED', created_at TEXT NOT NULL, decided_at TEXT);
CREATE TABLE IF NOT EXISTS shipments(id TEXT PRIMARY KEY, seller_order_id TEXT NOT NULL REFERENCES seller_orders(id) ON DELETE CASCADE, provider TEXT NOT NULL, tracking_id TEXT NOT NULL, status TEXT NOT NULL, charge_paisa BIGINT NOT NULL DEFAULT 0, mode TEXT NOT NULL DEFAULT 'sandbox', created_at TEXT NOT NULL, UNIQUE(provider,tracking_id));
CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, rating BIGINT NOT NULL CHECK(rating BETWEEN 1 AND 5), comment TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, UNIQUE(product_id,user_id));
CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, title TEXT NOT NULL, body TEXT NOT NULL DEFAULT '', read BIGINT NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs(id TEXT PRIMARY KEY, actor_id TEXT, action TEXT NOT NULL, entity TEXT NOT NULL, entity_id TEXT, detail TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL);
